func RasHistogram(g *port.Bitmap, hist *port.Cells) int32 {
	// 256 bins of channel 0, one port call per pixel. Clears `hist`.
	var w int32 = port.BitmapW(g)
	var h int32 = port.BitmapH(g)
	var i int32 = 0
	var x int32 = 0
	var y int32 = 0
	var v int32 = 0
	var n int32 = 0
	port.CellsDrop(hist, 0)
	for i < 256 {
		port.CellsPush(hist, 0)
		i += 1
	}
	for y < h {
		x = 0
		for x < w {
			v = port.BitmapU8(g, x, y, 0)
			n = port.CellsAt(hist, v)
			port.CellsSet(hist, v, n+1)
			x += 1
		}
		y += 1
	}
	return 0
}

func RasOtsu(hist *port.Cells, total int32) int32 {
	// Otsu's threshold from a 256-bin histogram: the level t that
	// maximises wb*wf*(mb-mf)^2, class B being levels 0..t. Integer
	// means (quot), so every target takes the same decision. The first
	// maximum wins. Ink is then gray <= t.
	var sum int64 = 0
	var sb int64 = 0
	var wb int64 = 0
	var wf int64 = 0
	var mb int64 = 0
	var mf int64 = 0
	var d int64 = 0
	var between int64 = 0
	var best int64 = -1
	var thr int32 = 0
	var t int32 = 0
	var hv int32 = 0
	for t < 256 {
		hv = port.CellsAt(hist, t)
		sum += int64(t) * int64(hv)
		t += 1
	}
	t = 0
	for t < 256 {
		hv = port.CellsAt(hist, t)
		wb += int64(hv)
		sb += int64(t) * int64(hv)
		wf = int64(total) - wb
		if wb > 0 {
			if wf > 0 {
				mb = sb / wb
				mf = (sum - sb) / wf
				d = mb - mf
				between = (wb * wf) * (d * d)
				if between > best {
					best = between
					thr = t
				}
			}
		}
		t += 1
	}
	return thr
}

func RasBinarise(g *port.Bitmap, m *port.Bitmap, thr int32) int32 {
	// mask = 255 where gray <= thr (ink), else 0. Answers the ink count.
	var w int32 = port.BitmapW(g)
	var h int32 = port.BitmapH(g)
	var x int32 = 0
	var y int32 = 0
	var ink int32 = 0
	for y < h {
		x = 0
		for x < w {
			if port.BitmapU8(g, x, y, 0) <= thr {
				port.BitmapSetU8(m, x, y, 0, 255)
				ink += 1
			} else {
				port.BitmapSetU8(m, x, y, 0, 0)
			}
			x += 1
		}
		y += 1
	}
	return ink
}

